import React from 'react';
import menuData, { categories } from '../mockData'; // Import the data
import './HomePage.css';

function HomePage() {
  // Get just the 'Appetizers' for example
  const appetizers = menuData.filter(
    (item) => item.category === 'Appetizers'
  );

  return (
    <div className="homepage">
      <h1>Restaurant Menu</h1>

      {/* Example: Displaying the Appetizers */}
      <h2>Appetizers</h2>
      <div className="menu-category">
        {appetizers.map((item) => (
          <div className="menu-item" key={item.id}>
            <img src={item.image} alt={item.name} className="menu-item-image" />
            <div className="menu-item-details">
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <span className="price">₹{item.price}</span>
            </div>
          </div>
        ))}
      </div>

      {/* You can create more sections for other categories... */}
      <h2>Soups</h2>
      {/* ...map over soups here... */}
    </div>
  );
}

export default HomePage;
